public class Main {
    sealed interface B permits K { }
    record K(int s) implements B { }

    static int luas(B b) {
        if (b instanceof K k) return k.s() * k.s();
        return 0;
    }

    public static void main(String[] args) {
        System.out.println(luas(new K(5)));
    }
}

